-- ==============================================================================
-- INSTRUCTIONS:
-- 1. Just change the @target_user_id number below (e.g. 21, 22, 23, 10, etc.)
-- 2. Run / Paste this script into phpMyAdmin, MySQL Workbench, HeidiSQL, or CLI.
-- 3. It will automatically:
--    - Update that user's Checking & Savings balances.
--    - Remove old seeded transactions for that user (if re-running).
--    - Generate 100% unique transaction hashes (TRX{user_id}X...) for all 2,624 records.
--    - Zero duplicate key errors, zero conflicts with any other users!
-- ==============================================================================

SET @target_user_id = 21; -- <<< CHANGE USER ID HERE (e.g., 22, 23, 24, etc.)
SET @checking_balance = '2160510.80';
SET @savings_balance  = '1749490.20';

-- 1. Set Account Balances for the target user
UPDATE `users` 
SET `balance` = @checking_balance, 
    `savings_balance` = @savings_balance 
WHERE `id` = @target_user_id;

-- 2. Clean up any previous transactions for this user (prevents duplicate key conflicts on re-run)
DELETE FROM `transactions` WHERE `user_id` = @target_user_id;

